-- ==========================================================
-- Gaming Analytics - Business Case Study #01
-- Company : Gaming Analytics
--
-- Business Problem:
-- Identify the top 3 best-selling games based on
-- total revenue generated.
-- ==========================================================


-- Select the top 3 games based on total revenue
SELECT TOP 3

    -- Game name
    g.Game,

    -- Calculate total revenue generated by each game
    SUM(s.Revenue) AS Total_Revenue

FROM Games g

-- Join Games with Sales using Game_id
INNER JOIN Sales s
    ON g.Game_id = s.Game_id

-- Calculate total revenue for each game
GROUP BY
    g.Game

-- Show the highest-revenue games first
ORDER BY
    Total_Revenue DESC;
